/**
 * The faces of Orochia's invented people — the demo cast (scripts/demo/cast.json) and the development seed.
 *
 * Fictional adults generated by Orazaka on one Mac (image-generation Studio, FLUX.2 [klein] 4B, Apache-2.0), owned by
 * Krizaka. One face = one persona = one product: these files live under `site/people/orochia/` on the Krizaka CDN and
 * no other product uses them. Prompts, seeds and credits: krizaka-com `lib/people.json` and `lib/people.credits.md`.
 * A URL is versioned by the file's hash, so it never changes content.
 */
export const PORTRAIT_ROOT = "https://krizaka-assets.b-cdn.net/site/people/orochia/";

export const PORTRAITS = {
  alex: { avatar: `${PORTRAIT_ROOT}alex-512.393c792cc4.webp`, thumb: `${PORTRAIT_ROOT}alex-256.1318632c62.webp` },
  elena: { avatar: `${PORTRAIT_ROOT}elena-512.2b78eb206e.webp`, thumb: `${PORTRAIT_ROOT}elena-256.33e980787a.webp` },
  mia: { avatar: `${PORTRAIT_ROOT}mia-512.e25ee38324.webp`, thumb: `${PORTRAIT_ROOT}mia-256.4f9a880f33.webp` },
  theo: { avatar: `${PORTRAIT_ROOT}theo-512.917838af21.webp`, thumb: `${PORTRAIT_ROOT}theo-256.d57df3427a.webp` },
  sam: { avatar: `${PORTRAIT_ROOT}sam-512.eb7c08cfb6.webp`, thumb: `${PORTRAIT_ROOT}sam-256.9e9253d33d.webp` },
  lina: { avatar: `${PORTRAIT_ROOT}lina-512.ac56b29f61.webp`, thumb: `${PORTRAIT_ROOT}lina-256.f1f6867eb8.webp` },
  operator: { avatar: `${PORTRAIT_ROOT}operator-512.66297a2918.webp`, thumb: `${PORTRAIT_ROOT}operator-256.4c77f1a4f5.webp` },
} as const;

export type Persona = keyof typeof PORTRAITS;

/** The persona's avatar (512 px). */
export const portrait = (persona: Persona): string => PORTRAITS[persona].avatar;

/** What the seed wrote before the portraits: stock photos of real people, replaced on the next seed. */
export const RETIRED_AVATAR_PREFIX = "https://images.unsplash.com/";
